function ChapterEntry:LoadScene(sceneName)

    local operation = SceneManagement.SceneManager.LoadSceneAsync(sceneName, SceneManagement.LoadSceneMode.Additive)
    operation.allowSceneActivation = false
    if not operation.isDone then
        while operation.progress < 0.8 do
            coroutine.yield(Yielders.EndOfFrame)
        end
        operation.allowSceneActivation = true

        while not operation.isDone do
            coroutine.yield(Yielders.EndOfFrame)
        end
