function ChapterEntry:UnloadScene(sceneName)

    local co = SceneManagement.SceneManager.UnloadSceneAsync(sceneName)

    while not co.isDone do
        coroutine.yield(Yielders.EndOfFrame)
    end
    
end

function ChapterEntry:OnDirectorFinish()
    CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self._go) then
            GameObject.Destroy(self._go)
        end

        self.controller:Close()
        --coroutine.yield(Yielders.EndOfFrame)

    end))
end

function ChapterEntry:OnChapterStart(go)
    if not isNull(go) then
        self._go = go
    end

    if self._onStart ~= nil then
        self._onStart(nil)
    end
end

return ChapterEntry